 28	int main(int argc, char **argv)
 29	{
 30	    char *progname = argv[0];
 31	
 32	    /* process command line options */
 33	    options.vm = 0;
 34	    options.extended = 0;
 35	    while ((argc > 1) && (argv[1][0] == '-') && (argv[1][1] == '-')) {
 36	        char *option = &argv[1][2];
 37	
 38	        if (strcmp(option, "vm") == 0) {
 39	            options.vm = 1;
 40	        } else if (strcmp(option, "extended") == 0) {
 41	            options.extended = 1;
 42	        } else {
 43	            error("%s: invalid option\nusage: %s %s\n", progname,
 44	                  progname, ARGS);
 45	        }
 46	        argc--;
 47	        argv++;
 48	    }
 49	    if (options.vm == 1) {
 50	        error("%s: option --vm not implemented\n", progname);
 51	    }
 52	    if (argc < 3) {
 53	        /* at least 3 args (createimage bootblock kernel) */
 54	        error("usage: %s %s\n", progname, ARGS);
 55	    }
 56	    create_image(argc - 1, argv + 1);
 57	    return 0;
 58	}
