 60	static void create_image(int nfiles, char *files[])
 61	{
 62	    int ph, nbytes = 0;
 63	    FILE *fp, *img;
 64	    Elf64_Ehdr ehdr;
 65	    Elf64_Phdr phdr;
 66	
 67	    /* open the image file */
 68		img = fopen(IMAGE_FILE, "wb");
 69		
 70	    /* for each input file */
 71	    while (nfiles-- > 0) {
 72	
 73	        /* open input file */
 74			fp = fopen(*files, "rb");
 75			
 76	        /* read ELF header */
 77	        read_ehdr(&ehdr, fp);
 78	        printf("0x%04lx: %s\n", ehdr.e_entry, *files);
 79	
 80	        /* for each program header */
 81	        for (ph = 0; ph < ehdr.e_phnum; ph++) {
 82	
 83	            /* read program header */
 84	            read_phdr(&phdr, fp, ph, ehdr);
 85	
 86	            /* write segment to the image */
 87	            write_segment(phdr, fp, img, &nbytes);
 88	            
 89	            /* print info of segment */
 90	            if(options.extended) {
 91		        	printf("\tsegment %d\n", ph);
 92					printf("\t\toffset 0x%04lx\t\tvaddr 0x%08lx\n", phdr.p_offset,phdr.p_vaddr);
 93					printf("\t\tfilesz 0x%04lx\t\tmemsz 0x%04lx\n", phdr.p_filesz,phdr.p_memsz);
 94					printf("\t\twriting 0x%04lx bytes\n", phdr.p_memsz);
 95					printf("\t\tpadding up to 0x%04x\n", nbytes);
 96				}
 97	        }
 98	
 99	        fclose(fp);
100	        files++;
101	    }
102	
103	    write_os_size(nbytes, img);
104	    fclose(img);
105	    
106	    return;
107	}
