109	static void read_ehdr(Elf64_Ehdr * ehdr, FILE * fp)
110	{
111		fread(ehdr, sizeof(Elf64_Ehdr), 1, fp);
112		return;
113	}
114	
115	static void read_phdr(Elf64_Phdr * phdr, FILE * fp, int ph,
116	                      Elf64_Ehdr ehdr)
117	{
118		fseek(fp, ehdr.e_phoff + ph * (sizeof(Elf64_Phdr)), SEEK_SET);
119		fread(phdr, sizeof(Elf64_Phdr), 1, fp);
120		return;
121	}
122	
123	static void write_segment(Elf64_Phdr phdr, FILE * fp,
124	                          FILE * img, int *nbytes)
125	{
126		/* 512 bytes align */
127		int bytes;
128		if(phdr.p_memsz % 512 == 0) {
129			bytes = phdr.p_memsz;
130		}
131		else {
132			bytes = phdr.p_memsz + (512 - phdr.p_memsz % 512);
133		}
134		
135		/* initialize the data array */
136		char segment_file[bytes];
137		int i;
138		for(i = 0; i < bytes; i++) {
139			segment_file[i] = 0;
140		}
141		
142		/* write data to img */
143		fseek(fp, phdr.p_offset, SEEK_SET);
144		fread(segment_file, phdr.p_filesz, 1, fp);
145		fseek(img, (*nbytes), SEEK_SET);
146		fwrite(segment_file, bytes, 1, img);
147		(*nbytes) += bytes;
148		
149		return;
150	}
151	
152	static void write_os_size(int nbytes, FILE * img)
153	{
154		long OS_SIZE_LOC = 508;
155		nbytes = nbytes / 512 - 1;
156		fseek(img, OS_SIZE_LOC, SEEK_SET);
157		fwrite(&nbytes, 2, 1, img);
158		printf("os_size: %d sectors\n", nbytes);
159		return;
160	}
